'use client';
import { useEffect, useImperativeHandle, useRef, useState, type ReactNode, type Ref } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useReducedMotion } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { Swap, Think, Tip, useGrow } from '../lib/motion';
import '../designme.css';
import './rewrite-toolbar.css';

/** A button in the toolbar, like Clearer or Shorter */
export interface RewriteAction {
  key: string;
  label: string;
  icon?: IconName;
}

/** What a ref to the toolbar can do: drive it from a shortcut, a command menu or a scripted demo */
export interface RewriteToolbarHandle {
  /** Rewrites the selected sentence with one of the actions, as a click on that action does */
  rewrite: (action: string) => void;
  /** Keeps the rewrite that is waiting for review */
  accept: () => void;
  /** Puts the sentence back as it was */
  undo: () => void;
}

export interface RewriteToolbarProps {
  /** The document's name */
  title: ReactNode;
  /** The file type tag in front of the name. Defaults to DOC */
  kind?: string;
  /** The text, one sentence each, so a click picks a sentence */
  sentences?: string[];
  defaultSentences?: string[];
  /** Called with every sentence once a rewrite is accepted */
  onSentencesChange?: (sentences: string[]) => void;
  /** Index of the sentence with the toolbar on it, or null. Leave it out to let clicks pick it */
  selected?: number | null;
  defaultSelected?: number | null;
  onSelectedChange?: (index: number | null) => void;
  /** Defaults to Clearer, Shorter and Friendlier */
  actions?: RewriteAction[];
  /** Writes the new sentence. While it works the toolbar says Rewriting; the answer is then written in word by word.
      If it throws, the sentence is left as it was */
  onRewrite: (sentence: string, action: string, index: number) => Promise<string> | string;
  /** The wand at the end of the toolbar. Left out, it rewrites with the first action */
  onAsk?: (sentence: string, index: number) => void;
  /** The tip on the wand */
  askLabel?: string;
  /** The shortcut shown in that tip */
  askShortcut?: string;
  ref?: Ref<RewriteToolbarHandle>;
  className?: string;
}

const ACTIONS: RewriteAction[] = [{ key: 'clear', label: 'Clearer', icon: 'spark' }, { key: 'short', label: 'Shorter' }, { key: 'warm', label: 'Friendlier' }];

type Job = { index: number; old: string; text?: string; shown: number };

/** Click a sentence and a small toolbar offers rewrites; the new text is written in beside the old one, to accept or undo. */
export function RewriteToolbar({
  title, kind = 'DOC', sentences, defaultSentences = [], onSentencesChange, selected, defaultSelected = null, onSelectedChange,
  actions = ACTIONS, onRewrite, onAsk, askLabel = 'Ask the agent', askShortcut = '⌘K', ref, className
}: RewriteToolbarProps) {
  const [text, setText] = useControllable(sentences, defaultSentences, onSentencesChange);
  const [sel, setSel] = useControllable(selected, defaultSelected, onSelectedChange);
  const [job, setJob] = useState<Job | null>(null);
  const [status, setStatus] = useState('Click a sentence');
  const reduce = useReducedMotion();
  const root = useRef<HTMLDivElement>(null);
  const bar = useRef<HTMLDivElement>(null);
  const head = useRef<HTMLDivElement>(null);
  const spans = useRef<(HTMLSpanElement | null)[]>([]);
  const [at, setAt] = useState<{ left: number; top: number }>({ left: 0, top: 0 });
  // no room is kept for a rewrite: the text grows as its words arrive and shrinks once one is kept, and the card eases with
  // it. Only the text clips while it eases, so the toolbar never does
  const [doc, docIn] = useGrow();
  const busy = job !== null;
  // the toolbar turns to Rewritten one beat after the last word, as the site does
  const phase = !busy ? 'menu' : job.text !== undefined && job.shown > words(job.text).length ? 'review' : 'working';
  // while the toolbar fades away it keeps what it last showed
  const [last, setLast] = useState(phase);
  if (sel !== null && phase !== last) setLast(phase);
  const view = sel !== null ? phase : last;

  // a new selection from outside says the same as a click does
  useEffect(() => { if (sel !== null && !busy) setStatus('Pick a rewrite'); }, [sel]); // eslint-disable-line react-hooks/exhaustive-deps

  // the toolbar sits above the sentence's first line, or under its last when above would cover the header, gliding down
  // with it as the new words add lines. A toolbar that isn't showing yet jumps to its place
  const shown = useRef(false);
  useIsoLayoutEffect(() => {
    const el = sel === null ? null : spans.current[sel], tb = bar.current, box = root.current;
    const jump = !shown.current; shown.current = sel !== null;
    if (!el || !tb || !box) return;
    const br = box.getBoundingClientRect(), k = br.width / box.offsetWidth || 1, rects = el.getClientRects(), f = rects[0]; if (!f) return;
    const left = Math.max(8, Math.min((f.left - br.left) / k, box.offsetWidth - tb.offsetWidth - 8));
    let top = (f.top - br.top) / k - tb.offsetHeight - 8;
    if (top < (head.current ? (head.current.getBoundingClientRect().bottom - br.top) / k : 4)) top = (rects[rects.length - 1].bottom - br.top) / k + 8;
    if (jump) { tb.style.transitionProperty = 'opacity,transform,filter'; tb.style.left = left + 'px'; tb.style.top = top + 'px'; void tb.offsetWidth; tb.style.transitionProperty = ''; }
    setAt({ left, top });
  }, [sel, view, job?.text, job?.shown]);

  // a click anywhere else puts the toolbar away, unless a rewrite is waiting on an answer
  const latest = useRef({ busy, setSel });
  useEffect(() => { latest.current = { busy, setSel }; });
  useEffect(() => {
    const down = (e: PointerEvent) => { const l = latest.current; if (!l.busy && !root.current?.contains(e.target as Node)) l.setSel(null); };
    document.addEventListener('pointerdown', down);
    return () => document.removeEventListener('pointerdown', down);
  }, []);

  // the answer is written in a word at a time
  useEffect(() => {
    if (!job?.text || job.shown > words(job.text).length) return;
    const t = setTimeout(() => setJob(j => j && { ...j, shown: reduce ? words(j.text!).length + 1 : j.shown + 1 }), job.shown === 0 ? 0 : 55);
    return () => clearTimeout(t);
  }, [job, reduce]);

  const pick = (i: number) => { if (busy) return; setSel(i); setStatus('Pick a rewrite'); };
  const rewrite = async (action: string) => {
    if (sel === null || busy) return;
    const index = sel, old = text[index];
    setJob({ index, old, shown: 0 });
    let out: string;
    // if the rewrite fails, the sentence goes back as it was and the toolbar offers the rewrites again
    try { out = await onRewrite(old, action, index); } catch { setJob(null); return; }
    setJob(j => j && j.index === index ? { ...j, text: out } : j);
  };
  const finish = (keep: boolean) => {
    if (!job?.text) return;
    if (keep) setText(text.map((s, i) => i === job.index ? job.text! : s));
    setJob(null); setSel(null); setStatus(keep ? 'Saved' : 'Click a sentence');
  };

  useImperativeHandle(ref, () => ({ rewrite, accept: () => finish(true), undo: () => finish(false) }));

  return (
    <div data-dm="" ref={root} className={cx('dm-rwx dm-panel', className)}>
      <div ref={head} className="dm-rwx-h"><span className="dm-ft">{kind}</span><span>{title}</span><Swap className="dm-muted dm-rwx-st">{status}</Swap></div>
      <div ref={doc} className="dm-rwx-doc dm-growing">
        <div ref={docIn} className="dm-grow">
        {text.map((s, i) => {
          const mine = job?.index === i;
          return (
            <span key={i}>
              {i > 0 && ' '}
              <span ref={el => { spans.current[i] = el; }} className={cx('dm-rwx-s', sel === i && 'dm-sel')} onClick={e => { e.stopPropagation(); if (!mine) pick(i); }}>
                {/* the new words arrive one at a time after the struck sentence, each only once it is written */}
                {mine ? <><del>{job.old}</del> <ins>{job.text && words(job.text).slice(0, job.shown).map((w, k) => <span key={k} className="dm-w">{w} </span>)}</ins></> : s}
              </span>
            </span>
          );
        })}
        </div>
      </div>
      <div ref={bar} className={cx('dm-rwx-tb', sel !== null && 'dm-show', view !== 'menu' && 'dm-act')} role="toolbar" aria-label="Rewrite" inert={sel === null} style={at}>
        {view === 'menu' ? (
          <>
            {actions.map(a => <button type="button" key={a.key} className="dm-rwx-b" onClick={() => rewrite(a.key)}>{a.icon && <Icon name={a.icon} size="xs" />}{a.label}</button>)}
            <span className="dm-rwx-sep" />
            <Tip label={askLabel} kbd={askShortcut}>
              <button type="button" className="dm-rwx-b dm-ic" aria-label={askLabel} onClick={() => (onAsk && sel !== null ? onAsk(text[sel], sel) : rewrite(actions[0].key))}><Icon name="wand" size="xs" /></button>
            </Tip>
          </>
        ) : view === 'working' ? (
          <span className="dm-lbl"><Think /><span className="dm-shim">Rewriting</span></span>
        ) : (
          <>
            <span className="dm-lbl"><Icon name="check" size="xs" />Rewritten</span>
            <button type="button" className="dm-rwx-b dm-rwx-un" onClick={() => finish(false)}>Undo</button>
            <button type="button" className="dm-pill dm-accent dm-sm dm-rwx-ok" onClick={() => finish(true)}>Accept</button>
          </>
        )}
      </div>
    </div>
  );
}

const words = (s: string) => s.split(' ');

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Rewrite toolbar ---------- */
/* a document whose sentences you click; a small toolbar over the one you pick offers rewrites, and the new sentence is
   written in after the old one, struck, a word at a time, to accept or undo. No room is kept for the words to come (owner,
   18 Nov): the text grows as they arrive (grow()), the card with it, and the toolbar glides along under the last line */
.dm-rwx{padding:var(--dm-s-4);position:relative}
.dm-rwx-h{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px;font-weight:500;margin-bottom:10px}
.dm-rwx-st{margin-left:auto;font-weight:400;font-size:12px}
.dm-rwx-doc{font-size:14px;line-height:24px;color:var(--dm-fg2)}
/* grow() wraps the text: it stays one flowing paragraph */
.dm-rwx-doc>.dm-grow{display:block}
.dm-rwx-s{border-radius:var(--dm-r-tiny,5px);cursor:text;transition:background .3s,color .3s;padding:1px 0;box-decoration-break:clone;-webkit-box-decoration-break:clone}
@media (hover:hover) and (pointer:fine){.dm-rwx-s:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-rwx-s.dm-sel{background:var(--dm-sel);color:var(--dm-fg)}
/* once it holds a rewrite, the struck words and the new ones say which sentence it is: the tint goes, so the words still
   fading in never show as an empty tinted band ahead of the text */
.dm-rwx-s.dm-sel:has(ins){background:none}
.dm-rwx-s.dm-sel del{color:var(--dm-fg2)}
/* the words it replaces keep the text grey and are struck with the bright red mark; the new ones are in the text colour */
.dm-rwx-s del{color:var(--dm-muted);text-decoration-color:var(--dm-bad-mark)}
.dm-rwx-s ins{text-decoration:none;color:var(--dm-fg)}
.dm-rwx-s ins .dm-w{animation:dm-rww .4s var(--dm-ease) both}
@keyframes dm-rww{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.dm-rwx-tb{position:absolute;left:0;top:0;display:flex;align-items:center;gap:2px;padding:var(--dm-s-1);border-radius:var(--dm-r-pill);background:var(--dm-ink);color:var(--dm-on-ink);box-shadow:var(--dm-shadow-pop);opacity:0;pointer-events:none;transform:translateY(6px) scale(.96);filter:blur(4px);transition:opacity .3s var(--dm-ease),transform .4s var(--dm-ease),filter .3s,top var(--dm-t) var(--dm-ease),left var(--dm-t) var(--dm-ease);z-index:3;white-space:nowrap}
.dm-rwx-tb.dm-show{opacity:1;pointer-events:auto;transform:none;filter:none}
/* "Rewriting" shimmers while the agent writes, in the toolbar's own ink; done, the tick is the vivid mark green */
.dm-rwx-tb .dm-shim{background-image:linear-gradient(90deg,var(--dm-on-ink) 0%,var(--dm-on-ink) 38%,color-mix(in srgb,var(--dm-on-ink) 35%,var(--dm-ink)) 50%,var(--dm-on-ink) 62%,var(--dm-on-ink) 100%)}
.dm-rwx-tb .dm-lbl>svg{color:var(--dm-ok-mark)}
.dm-rwx-b{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 11px;border-radius:var(--dm-r-pill);font-size:12.5px;color:inherit;opacity:.85;transition:background .2s,opacity .2s}
.dm-rwx-b.dm-hl{background:color-mix(in srgb,var(--dm-on-ink) 14%,transparent);opacity:1}
@media (hover:hover) and (pointer:fine){.dm-rwx-b:hover{background:color-mix(in srgb,var(--dm-on-ink) 14%,transparent);opacity:1}}
.dm-rwx-b.dm-ic{width:28px;padding:0;justify-content:center}
.dm-rwx-sep{width:1px;height:16px;background:color-mix(in srgb,var(--dm-on-ink) 25%,transparent);margin:0 2px}
.dm-rwx-tb.dm-act{padding:var(--dm-s-1) var(--dm-s-1) var(--dm-s-1) var(--dm-s-3)}
.dm-rwx-tb .dm-lbl{font-size:12.5px;margin-right:6px;display:flex;align-items:center;gap:7px}
.dm-rwx-tb .dm-pill.dm-sm{height:28px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's primary alone presses */
.dm-rwx .dm-pill:active{transform:none}
/* in dark mode the toolbar is the raised dark surface with a hairline, not the inverted light ink (owner, 10 Nov) */
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-rwx-tb{--dm-ink:var(--dm-raised);--dm-on-ink:var(--dm-fg);box-shadow:var(--dm-shadow-pop),inset 0 0 0 1px color-mix(in srgb,var(--dm-fg) 12%,transparent)}}
:root[data-theme="dark"] .dm-rwx-tb{--dm-ink:var(--dm-raised);--dm-on-ink:var(--dm-fg);box-shadow:var(--dm-shadow-pop),inset 0 0 0 1px color-mix(in srgb,var(--dm-fg) 12%,transparent)}
@media (prefers-reduced-motion:reduce){.dm-rwx-tb .dm-shim{color:var(--dm-on-ink);background:none}}
/* Clean (owner, 19 Nov): its content 16px from every edge; the file's mark is the neutral grey every Clean file mark is.
   The toolbar is the ink pill (black in light, the raised grey in dark) and opens from the sentence by scaling and fading,
   with no blur; its Accept is the white button, so it stands out on the ink (the dark mode's white button, with its faint
   glow only in dark). Words fade in without a blur */
:root[data-style="clean"] .dm-rwx.dm-panel,:root [data-style="clean"] .dm-rwx.dm-panel,:root [data-style="clean"].dm-rwx.dm-panel{padding:16px}
:root[data-style="clean"] .dm-rwx-h .dm-ft,:root [data-style="clean"] .dm-rwx-h .dm-ft,:root [data-style="clean"].dm-rwx-h .dm-ft{color:var(--dm-muted)}
:root[data-style="clean"] .dm-rwx-tb,:root [data-style="clean"] .dm-rwx-tb,:root [data-style="clean"].dm-rwx-tb{filter:none;transform:translateY(4px) scale(.96);transform-origin:top left;transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease),top var(--dm-t) var(--dm-ease),left var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .dm-rwx-tb.dm-show,:root [data-style="clean"] .dm-rwx-tb.dm-show,:root [data-style="clean"].dm-rwx-tb.dm-show{transform:none}
:root[data-style="clean"] .dm-rwx-b,:root [data-style="clean"] .dm-rwx-b,:root [data-style="clean"].dm-rwx-b{transition:background-color var(--dm-t-fast) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-rwx-s,:root [data-style="clean"] .dm-rwx-s,:root [data-style="clean"].dm-rwx-s{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-rwx-s ins .dm-w,:root [data-style="clean"] .dm-rwx-s ins .dm-w,:root [data-style="clean"].dm-rwx-s ins .dm-w{animation:dm-rwwc var(--dm-t-fast) var(--dm-ease) both}
@keyframes dm-rwwc{from{opacity:0}}
:root[data-style="clean"] .dm-rwx-tb,:root [data-style="clean"] .dm-rwx-tb,:root [data-style="clean"].dm-rwx-tb{--dm-btn-1:#ffffff;--dm-btn-2:#e0e0e0;--dm-on-btn:#0a0a0a;--dm-btn-depth:inset 0 0 0 1px rgba(245,245,245,.9),inset 0 3px 5px -2px #ffffff,inset 0 -3px 5px -3px rgba(0,0,0,.18),0 1px 2px rgba(0,0,0,.5);--dm-btn-press:inset 0 0 0 1px rgba(245,245,245,.9),inset 0 1px 3px rgba(0,0,0,.3),inset 0 -3px 5px -3px rgba(0,0,0,.2),0 1px 1px rgba(0,0,0,.4)}
@media (prefers-color-scheme:dark){:root[data-style="clean"]:not([data-theme="light"]) .dm-rwx-tb,:root:not([data-theme="light"]) [data-style="clean"] .dm-rwx-tb,:root:not([data-theme="light"]) [data-style="clean"].dm-rwx-tb{--dm-btn-depth:inset 0 0 0 1px rgba(245,245,245,.9),inset 0 3px 5px -2px #ffffff,inset 0 -3px 5px -3px rgba(0,0,0,.18),0 1px 2px rgba(0,0,0,.5),0 0 14px rgba(255,255,255,.16)}}
:root[data-style="clean"][data-theme="dark"] .dm-rwx-tb,:root[data-theme="dark"] [data-style="clean"] .dm-rwx-tb,:root[data-theme="dark"] [data-style="clean"].dm-rwx-tb{--dm-btn-depth:inset 0 0 0 1px rgba(245,245,245,.9),inset 0 3px 5px -2px #ffffff,inset 0 -3px 5px -3px rgba(0,0,0,.18),0 1px 2px rgba(0,0,0,.5),0 0 14px rgba(255,255,255,.16)}

